export type ShirtItemKey = Brand<string, "ShirtItemKey">;

export type ShirtItem = {
  key: ShirtItemKey;

  customName?: string | null;
};

export type ShirtItemInfo = {
  key: ShirtItemKey;
  ped: string;
  type: string;
  componentId: number;
  drawableId: number;
  textureId: number;
  name: string;
  price: number;
  restrictionTags: string[] | null;
};

export const shirts: Record<ShirtItemKey, ShirtItemInfo> = SHIRT_ITEMS as Record<
  ShirtItemKey,
  ShirtItemInfo
>;

/**
 * Register all melee weapons.
 */
for (const [key, info] of Object.entries(shirts)) {
  registerItem(key as ShirtItemKey, info);
}

/**
 * Type guards for melee weapons
 */
export function isItemKeyShirt(key: string): key is ShirtItemKey {
  return key in shirts;
}

export function isItemShirt(item: Item): item is ShirtItem {
  return isItemKeyShirt(item.key);
}
